--
-- Name: v_active_index_tasks; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.v_active_index_tasks AS
 SELECT t.id,
    t.task_id,
    t.doc_id,
    t.task_type,
    t.status,
    t.priority,
    t.retry_count,
    t.max_retries,
    t.error_message,
    t.progress,
    t.metadata,
    t.created_at,
    t.started_at,
    t.completed_at,
    t.updated_at,
    d.filename,
    d.namespace,
    EXTRACT(epoch FROM (CURRENT_TIMESTAMP - (t.created_at)::timestamp with time zone)) AS age_seconds
   FROM (public.index_tasks t
     LEFT JOIN public.documents d ON ((t.doc_id = d.id)))
  WHERE ((t.status)::text = ANY ((ARRAY['pending'::character varying, 'processing'::character varying])::text[]))
  ORDER BY t.priority DESC, t.created_at;


ALTER VIEW public.v_active_index_tasks OWNER TO postgres;

--
-- Name: v_index_status_summary; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.v_index_status_summary AS
 SELECT COALESCE(namespace, 'default'::character varying) AS namespace,
    count(*) AS total_docs,
    count(
        CASE
            WHEN ((index_status)::text = 'indexed'::text) THEN 1
            ELSE NULL::integer
        END) AS indexed_docs,
    count(
        CASE
            WHEN ((index_status)::text = 'pending'::text) THEN 1
            ELSE NULL::integer
        END) AS pending_docs,
    count(
        CASE
            WHEN ((index_status)::text = 'failed'::text) THEN 1
            ELSE NULL::integer
        END) AS failed_docs,
    count(
        CASE
            WHEN ((index_status)::text = 'outdated'::text) THEN 1
            ELSE NULL::integer
        END) AS outdated_docs,
    max(last_indexed_at) AS last_index_time
   FROM public.documents d
  GROUP BY namespace;


ALTER VIEW public.v_index_status_summary OWNER TO postgres;

--
-- Name: v_table_size_stats; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.v_table_size_stats AS
 SELECT schemaname,
    tablename,
    pg_size_pretty(pg_total_relation_size(((((schemaname)::text || '.'::text) || (tablename)::text))::regclass)) AS total_size,
    pg_size_pretty(pg_relation_size(((((schemaname)::text || '.'::text) || (tablename)::text))::regclass)) AS table_size,
    pg_size_pretty((pg_total_relation_size(((((schemaname)::text || '.'::text) || (tablename)::text))::regclass) - pg_relation_size(((((schemaname)::text || '.'::text) || (tablename)::text))::regclass))) AS indexes_size
   FROM pg_tables
  WHERE (schemaname = 'public'::name)
  ORDER BY (pg_total_relation_size(((((schemaname)::text || '.'::text) || (tablename)::text))::regclass)) DESC;


ALTER VIEW public.v_table_size_stats OWNER TO postgres;

